-- Сид приказа о СИЗ (Минтруд 767н, Приложение №1): профессии, строки норм,
-- наборы норм и справочник номенклатуры СИЗ.
--
-- Сгенерировано помощником `backend-api/scripts/generate-ppe-order-data.mjs` из
-- документа «РМЗ Приказ о СИЗ (приложения).doc»; источник правды по данным —
-- `backend-api/src/data/ppeOrderNorms767.ts` (если файлы разошлись — правьте
-- генератор и документ, а не этот SQL).
--
-- Идемпотентно: фиксированные UUID + ON CONFLICT DO NOTHING. Повторный прогон
-- безвреден. Норма приказа (количество, единица, форма срока) разбирается
-- доменом `parseOrderNormQty` и в SQL не дублируется — здесь лежит РОВНО ТО,
-- что написано в документе.
-- 1. Профессии приказа: код пункта приложения → наименование профессии.
--> statement-breakpoint
-- 2. Строки нормы приказа («приказные» строки): наименование, тип СИЗ, норма
-- как написана в документе, привязка к профессии и источнику (ЕТН 767н или 766н).
--> statement-breakpoint
-- 3. Наборы норм: по профессии и по источнику. Зимний набор (766н) помечен
-- season='winter' — по п. 19 приказа СИЗ от пониженных температур выдаются
-- сезонно, то есть ПОВЕРХ основной нормы, а не вместо неё.
--> statement-breakpoint
-- 4. Строки наборов норм: привязка строки приказа к базовой позиции
-- номенклатуры и к «приказной» строке (spec_id). Размер сотрудника подставляется
-- при выдаче — дерево «база → размеры», поэтому в норме лежит базовая модель.
--> statement-breakpoint
-- 5. Привязка «приказная строка → базовая позиция номенклатуры». Это ключ
-- подстановки: привязал позицию один раз — карточка сама подставляет наименование,
-- единицу измерения, количество и пункт приложения.
UPDATE ppe_norm_line_specs s
   SET nomenclature_id = n.nomenclature_id
  FROM (
    SELECT spec_id, nomenclature_id FROM ppe_norm_lines
     WHERE deleted_at IS NULL AND spec_id IS NOT NULL
  ) n
 WHERE s.id = n.spec_id AND s.nomenclature_id IS NULL
   AND s.id IN ('2aef405a-38ea-5a34-a9ff-4e73070b1cbc', '9f281a09-f025-5468-a4ad-1eb4c2ab9f24', '5031c9e6-a301-535e-acf4-afb874f76184', '2fe6d9c0-5006-5756-a44d-d5a6f52ce3d8', 'a457f1d2-a2d6-565b-ad7a-c301d407df51', '9310688b-7f3e-533f-a4ea-be1780ad179d', '00800fab-6db3-56fd-a944-b279eba90d7e', '96f2771a-46d5-59f7-aef9-9d7c96b6746d', '6c444cd1-0858-50b3-a71b-2a3d307935de', '64ad9d6b-38e8-5f53-af5b-9ee3859253cf', 'ecd17a0d-e3a6-541d-a9b3-471be5d9ecbe', 'ce1106f4-0d62-585b-ac44-fdbc45e33231', 'db44ee4a-7907-5b57-ab32-5860145d96fc', '6c60c0e6-2240-590e-a915-c2a79cf1f0d9', '8ebd4c0b-0b4e-58a6-a788-4f144bc5a608', '08d43e08-0d72-5c7b-a727-643b031819a6', '09bd6c9a-5dff-5367-a7f3-ad1ffda62035', '6e86170c-e175-55b1-af27-211579e06324', 'e5795b16-c117-59ec-a77e-8b45dc501a3e', 'bdcfc526-81a3-5657-aeca-c7c15468637d', 'd153e912-4e93-56aa-a62b-0f3d92cdae79', 'e118eb72-bd59-5aeb-a414-9a13fd53f478', '67f125f9-0aed-5a5e-a265-6fc5cb7fb401', '200dfff3-f8b9-5e77-a8c5-3185a9e55a6e', 'a314729b-19e2-5003-a27b-0d53c7b15557', '82e32efa-4902-5789-a216-133945d57baa', 'e4988e47-1d95-5c3a-a25d-4303cc56b654', 'f06fb364-67f6-5490-accb-272e755f2850', '4643f779-0396-595b-acfb-82e41ac44e04', 'af3ef761-8860-5c98-ab07-8eaf9813661f', 'f9c5953c-975c-5367-afd5-0720739595b7', 'bc37cafb-57df-56cd-a4ae-06311f567fb3', '023648c8-9652-568b-afdd-a3d0d8845c06', '956d39c4-0716-5a75-a828-7f7a25009b93');
--> statement-breakpoint
-- 6. Номенклатура СИЗ: базовая позиция (без размера) и её размерный ряд.
-- Размер — отдельная позиция-вариант с родителем-базой (один уровень), как
-- заведено для остальной номенклатуры. Категория 'workwear' отделяет СИЗ от
-- деталей — в фонд деталей они не попадают.
--> statement-breakpoint
